package com.musiccatalog.service; import com.musiccatalog.dto.AuthDtos.*; import com.musiccatalog.entity.User; import com.musiccatalog.exception.ApiException; import com.musiccatalog.repository.UserRepository; import com.musiccatalog.security.JwtService; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class AuthService { private final UserRepository users;private final PasswordEncoder passwords;private final JwtService jwt; public AuthService(UserRepository u,PasswordEncoder p,JwtService j){users=u;passwords=p;jwt=j;} public TokenResponse register(Credentials c){if(users.existsByEmail(c.email().toLowerCase()))throw new ApiException(HttpStatus.CONFLICT,"Email is already registered");User u=new User();u.setEmail(c.email().toLowerCase());u.setPassword(passwords.encode(c.password()));users.save(u);return new TokenResponse(jwt.create(u.getEmail()));} public TokenResponse login(Credentials c){User u=users.findByEmail(c.email().toLowerCase()).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));if(!passwords.matches(c.password(),u.getPassword()))throw new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password");return new TokenResponse(jwt.create(u.getEmail()));} }
